import numpy as np

def problem(x: np.ndarray) -> float:
    n = x.shape[0]
    abs_term = np.sum(0.3 * np.abs(x)) #L1 norm
    interaction_term = 0.1 * np.sum(x * np.roll(x, 1) / (1 + np.exp(-x))) # Pairwise with sigmoid

    # Add a constraint penalty to discourage outside [-5, 5]
    penalty = 0.0
    for val in x:
        if abs(val) > 5:
            penalty += np.log(abs(val) - 4) # Logarithmic penalty

    # Inverse polynomial to modulate the function
    poly_term = 1.0 / (1.0 + np.sum(x**4))

    return float((abs_term + interaction_term + penalty) * poly_term * 0.5)
